-- Compute n explicitly
let n := 3 ^ 17 + 3 ^ 10;
have h_n := h₀.trans (by ring);
have h_digits : Nat.digits 10 n = [B, A, B, C, C, A, C, B, A] := h₆.trans h_n;

-- From the digits, we can extract the digit values
have h_B : B = 1 := by
  have : Nat.digits 10 n = [1, _, _, _, _, _, _, _, _] := by
    rw [h_digits];
    simp [Nat.digits]
  simp [this] at h_digits;
  rw [h_digits] at h_digits;
  simp [Nat.digits] at h_digits;
  exact h_digits.1;

have h_A : A = 2 := by
  have : Nat.digits 10 n = [1, 2, _, _, _, _, _, _, _] := by
    rw [h_digits];
    simp [Nat.digits]
  simp [this] at h_digits;
  rw [h_digits] at h_digits;
  simp [Nat.digits] at h_digits;
  exact h_digits.2;

have h_C : C = 9 := by
  have : Nat.digits 10 n = [1, 2, _, 9, _, _, _, _, _] := by
    rw [h_digits];
    simp [Nat.digits]
  simp [this] at h_digits;
  rw [h_digits] at h_digits;
  simp [Nat.digits] at h_digits;
  exact h_digits.3;

-- Verify the digit constraints
have h_distinct : A ≠ B ∧ A ≠ C ∧ B ≠ C := by
  simp [h_B, h_A, h_C];
  split;
  { exact Nat.not_le.mpr (Nat.lt.succ_le (Nat.lt_of_lt_of_le h_B h_A)) }
  { exact Nat.not_le.mpr (Nat.lt.succ_le (Nat.lt_of_lt_of_le h_A h_C)) }
  { exact Nat.not_le.mpr (Nat.lt.succ_le (Nat.lt_of_lt_of_le h_B h_C)) }

have h_range : A ∈ Finset.Icc 0 9 ∧ B ∈ Finset.Icc 0 9 ∧ C ∈ Finset.Icc 0 9 := by
  simp [h_B, h_A, h_C];
  split; split; split;
  { exact Nat.zero_le_one (Nat.lt_of_lt_of_le h_B Nat.zero_lt_one) }
  { exact Nat.one_le_nat (Nat.lt_one_nat h_B) }
  { exact Nat.zero_le_one (Nat.lt_of_lt_of_le h_A Nat.zero_lt_one) }
  { exact Nat.one_le_nat (Nat.lt_one_nat h_A) }
  { exact Nat.zero_le_one (Nat.lt_of_lt_of_le h_C Nat.zero_lt_one) }
  { exact Nat.one_le_nat (Nat.lt_one_nat h_C) }

have h_odd : Odd A ∧ Odd C := by
  simp [h_A, h_C];
  split;
  { exact Nat.odd_of_even (Nat.even_of_lt_two (Nat.lt_of_lt_of_le h_A Nat.zero_lt_two)) }
  { exact Nat.odd_of_even (Nat.even_of_lt_two (Nat.lt_of_lt_of_le h_C Nat.zero_lt_two)) }

have h_not_div3 : ¬3 ∣ B := by
  simp [h_B];
  exact Nat.not_divides_of_not_divides (Nat.not_divides_3_one)

-- Verify the divisibility condition
have h_div11 : 11 ∣ n + 1 := by
  have : n + 1 = 3 ^ 17 + 3 ^ 10 + 1 := by ring
  have : 3 ^ 17 + 3 ^ 10 + 1 = 129544321 := by
    ring_nf
  have : 129544321 % 11 = 0 := by
    have : 129544321 = 11 * 11776756 + 5 := by
      ring_nf
    simp [this]
    exact Nat.zero_lt_one
  exact this

-- Compute the final expression
have : 100 * A + 10 * B + C = 100 * 2 + 10 * 1 + 9 := by
  simp [h_A, h_B, h_C]
  ring
exact this
